// Turns the keystroke timeline (generated by sfx/build_audio.py) into a pose
// for any time t. Everything is a pure function of t, so scrubbing in
// Remotion Studio and rendering in parallel always agree.

import timeline from "../timeline.json";
import { clamp, deg, easeIn, easeInOut, easeOut, invLerp, lerp, noise1, smooth, springStep } from "../kit/math";

export type HandId = "near" | "far";

export interface Key {
  t: number;
  hand: "L" | "R";
  finger: number; // 0..2, -1 = thumb (space)
  row: number; // 0 bottom .. 2 top
  kind: "key" | "space" | "enter";
}

export const KEYS = timeline.keys as Key[];
export const PAUSE = timeline.pause as [number, number];
export const ENTER_T = timeline.enter as number;
export const BLINKS = timeline.blinks as number[];

// The right hand is the one facing the camera, so the final Enter is visible.
const handOf = (k: Key): HandId => (k.hand === "R" ? "near" : "far");

export interface HandPose {
  dx: number; // offset of wrist from rest (px)
  dy: number;
  rot: number; // extra wrist rotation (rad)
  fingers: [number, number, number]; // fingertip vertical offset (+ = pressed down)
  thumb: number;
}

export interface Pose {
  t: number;
  breath: number;
  lean: number;
  headTilt: number;
  hairSway: number;
  stringSway: number;
  blink: number;
  gazeX: number;
  gazeY: number;
  brow: number;
  smile: number;
  shoulder: number;
  screen: number;
  near: HandPose;
  far: HandPose;
}

/** Fingertip curve around a key press at d = t - tKey (seconds). Negative = lifted. */
const fingerCurve = (d: number, lift: number, press: number) => {
  if (d < -0.11 || d > 0.2) return 0;
  if (d < -0.035) return -lift * easeOut(invLerp(-0.11, -0.035, d));
  if (d < 0) return lerp(-lift, press, easeIn(invLerp(-0.035, 0, d)));
  if (d < 0.04) return press;
  // release with a tiny rebound past rest
  const r = invLerp(0.04, 0.2, d);
  return press * (1 - easeOut(r)) - Math.sin(r * Math.PI) * lift * 0.18;
};

const ROW_X = [-15, 0, 16];

const handPose = (id: HandId, t: number): HandPose => {
  const mine = KEYS.filter((k) => handOf(k) === id);
  const fingers: [number, number, number] = [0, 0, 0];
  let thumb = 0;
  let dy = 0;

  for (const k of mine) {
    const d = t - k.t;
    if (k.kind === "space") {
      thumb += fingerCurve(d, 4, 5);
      dy += Math.max(0, fingerCurve(d, 0, 2.4));
    } else if (k.kind === "enter") {
      // big confident press: lift hand, strike, spring back
      fingers[2] += fingerCurve(d, 5, 4.5);
    } else {
      fingers[k.finger] += fingerCurve(d, 9, 3.5);
      dy += Math.max(0, fingerCurve(d, 0, 2.2));
    }
  }

  // wrist slides forward/back towards the row of the next key
  let dx = ROW_X[1];
  const prev = [...mine].reverse().find((k) => k.t <= t);
  const next = mine.find((k) => k.t > t);
  const from = prev ? ROW_X[prev.row] : ROW_X[1];
  if (next) {
    const s = smooth(invLerp(next.t - 0.11, next.t - 0.025, t));
    dx = lerp(from, ROW_X[next.row], s);
  } else {
    dx = from;
  }

  // hover during the reading pause: hands float up a touch, fingers relax
  const pauseAmt = smooth(invLerp(PAUSE[0] + 0.02, PAUSE[0] + 0.22, t)) * (1 - smooth(invLerp(PAUSE[1] - 0.2, PAUSE[1] - 0.04, t)));
  dy -= pauseAmt * 6;
  const relax = pauseAmt * -3.5;
  fingers[0] += relax;
  fingers[1] += relax * 0.8;
  fingers[2] += relax * 0.6;

  let rot = 0;
  if (id === "near") {
    // Enter: anticipation lift -> reach -> strike -> settle
    const up = smooth(invLerp(ENTER_T - 0.26, ENTER_T - 0.06, t));
    const strike = easeIn(invLerp(ENTER_T - 0.06, ENTER_T, t));
    const settle = springStep(t - ENTER_T, 5, 0.5);
    const reach = smooth(invLerp(ENTER_T - 0.28, ENTER_T - 0.08, t));
    dx += reach * 15 * (1 - smooth(invLerp(ENTER_T + 0.15, ENTER_T + 0.55, t)));
    const lift = up * (1 - strike) * 18;
    dy += -lift + (t > ENTER_T ? 2.4 * (1 - settle) : 0);
    rot += deg(-7) * up * (1 - strike) + deg(1.5) * (t > ENTER_T ? 1 - settle : 0);
  }

  // after Enter both hands ease back and rest lighter on the keyboard
  const rest = smooth(invLerp(ENTER_T + 0.12, ENTER_T + 0.5, t));
  dx -= rest * (id === "near" ? 6 : 4);
  dy -= rest * 2.5;
  for (let i = 0; i < 3; i++) fingers[i] -= rest * 2;

  // tiny idle drift so the hands never freeze
  dx += noise1(t * 1.3, id === "near" ? 3 : 8) * 0.8;
  dy += noise1(t * 1.7, id === "near" ? 5 : 12) * 0.5;

  return { dx, dy, rot, fingers, thumb };
};

export const poseAt = (t: number): Pose => {
  const breath = Math.sin((t / 3.4) * Math.PI * 2 + 0.6);

  const pauseIn = smooth(invLerp(PAUSE[0], PAUSE[0] + 0.3, t));
  const pauseOut = smooth(invLerp(PAUSE[1] - 0.25, PAUSE[1] + 0.05, t));
  const reading = pauseIn * (1 - pauseOut);

  const enterAnt = smooth(invLerp(ENTER_T - 0.3, ENTER_T - 0.04, t));
  const enterHit = springStep(t - ENTER_T, 3.2, 0.42);
  const after = smooth(invLerp(ENTER_T + 0.05, ENTER_T + 0.6, t));

  // lean (radians, + = forward)
  const lean =
    deg(-3) * reading +
    deg(1.5) * enterAnt * (1 - (t > ENTER_T ? enterHit : 0)) +
    deg(-3.4) * after +
    noise1(t * 0.6, 41) * deg(0.3);

  const headTiltAt = (tt: number) => {
    const rd = smooth(invLerp(PAUSE[0], PAUSE[0] + 0.3, tt)) * (1 - smooth(invLerp(PAUSE[1] - 0.25, PAUSE[1] + 0.05, tt)));
    const nod = tt > ENTER_T ? Math.sin(Math.min(1, (tt - ENTER_T) / 0.34) * Math.PI) * deg(4.5) : 0;
    const aft = smooth(invLerp(ENTER_T + 0.15, ENTER_T + 0.7, tt));
    // micro bob while typing, in time with the keys
    let bob = 0;
    for (const k of KEYS) {
      const d = tt - k.t;
      if (d > 0 && d < 0.25) bob += Math.sin((d / 0.25) * Math.PI) * deg(0.45);
    }
    return deg(-7.5) * rd + nod - deg(5.5) * aft + bob + noise1(tt * 0.8, 17) * deg(0.6);
  };
  const headTilt = headTiltAt(t);
  // hair follows the head with a delay (secondary motion)
  const hairSway = (headTiltAt(t - 0.14) - headTilt) * 1.6 + (headTiltAt(t - 0.28) - headTilt) * 0.6;
  const stringSway = (headTiltAt(t - 0.2) - headTilt) * 1.2 + Math.sin(t * 5.1) * deg(0.6);

  // blinks: fast close, slower open
  let blink = 0;
  for (const b of BLINKS) {
    const d = t - b;
    if (d >= 0 && d < 0.05) blink = Math.max(blink, easeIn(d / 0.05));
    else if (d >= 0.05 && d < 0.085) blink = 1;
    else if (d >= 0.085 && d < 0.2) blink = Math.max(blink, 1 - easeOut((d - 0.085) / 0.115));
  }

  // gaze: little saccades while typing, a left-to-right read during the pause
  const sacc = Math.floor(t / 0.42);
  const sF = clamp(((t % 0.42) / 0.42 - 0.85) / 0.15);
  const typingGaze = lerp(noise1(sacc, 61) * 1.6, noise1(sacc + 1, 61) * 1.6, smooth(sF));
  const readGaze = lerp(-2.6, 2.6, easeInOut(invLerp(PAUSE[0] + 0.1, PAUSE[1] - 0.1, t)));
  const gazeX = lerp(typingGaze, readGaze, reading);
  const gazeY = reading * -0.8;

  const brow = reading * 0.7 + after * 0.5;
  const smile = smooth(invLerp(ENTER_T + 0.12, ENTER_T + 0.45, t));

  // tiny shoulder jiggle from typing impacts
  let shoulder = 0;
  for (const k of KEYS) {
    const d = t - k.t;
    if (d > 0 && d < 0.18) shoulder += Math.sin((d / 0.18) * Math.PI) * (k.kind === "enter" ? 2 : 0.6);
  }

  // screen brightness: flickers with new characters, brightens on Enter
  let screen = 1;
  for (const k of KEYS) {
    const d = t - k.t;
    if (d > 0) screen += Math.exp(-d / 0.08) * 0.045;
  }
  if (t > ENTER_T) screen += Math.exp(-(t - ENTER_T) / 0.18) * 0.35 + 0.1 * smooth((t - ENTER_T) / 0.2);

  return {
    t,
    breath,
    lean,
    headTilt,
    hairSway,
    stringSway,
    blink,
    gazeX,
    gazeY,
    brow,
    smile,
    shoulder,
    screen,
    near: handPose("near", t),
    far: handPose("far", t),
  };
};
